class CalibrationMethod(BaseEstimator):
    """Confidence-Adaptive Ensemble Calibration.

    Learns two complementary calibrators from probabilities alone:
    (1) global temperature scaling for stable NLL reduction, and
    (2) beta-style one-vs-rest calibration for flexible classwise correction.
    A learned confidence-dependent gate mixes them, applying stronger flexible
    correction mainly on confident predictions where miscalibration is largest.
    """

    def __init__(self):
        self.is_binary = None
        self.n_classes_ = None
        self.temperature_ = 1.0
        self.mix_ = np.zeros(2)
        self.models_ = None

    def _feat(self, p):
        p = np.clip(p, 1e-6, 1 - 1e-6)
        return np.column_stack([np.log(p), np.log(1 - p)])

    def _temp_predict(self, probs, T):
        eps = 1e-12
        if probs.ndim == 1:
            p = np.clip(probs, eps, 1 - eps)
            return special.expit((np.log(p) - np.log(1 - p)) / T)
        z = np.log(np.clip(probs, eps, 1.0)) / T
        z -= z.max(axis=1, keepdims=True)
        z = np.exp(z)
        return z / z.sum(axis=1, keepdims=True)

    def _beta_predict(self, probs):
        if self.is_binary:
            if self.models_[0] is None:
                return np.clip(probs, 1e-12, 1 - 1e-12)
            return self.models_[0].predict_proba(self._feat(probs))[:, 1]
        out = np.zeros_like(probs, dtype=float)
        for c, model in enumerate(self.models_):
            out[:, c] = probs[:, c] if model is None else model.predict_proba(self._feat(probs[:, c]))[:, 1]
        out = np.clip(out, 1e-12, 1.0)
        return out / out.sum(axis=1, keepdims=True)

    def fit(self, probs, labels):
        self.is_binary = probs.ndim == 1
        self.n_classes_ = 2 if self.is_binary else probs.shape[1]

        def nll_T(x):
            q = self._temp_predict(probs, float(np.exp(x[0])))
            q = np.column_stack([1 - q, q]) if q.ndim == 1 else q
            q = np.clip(q, 1e-12, 1 - 1e-12)
            return -np.log(q[np.arange(len(labels)), labels.astype(int)]).mean()

        res = optimize.minimize(nll_T, x0=[0.0], bounds=[(-3, 3)], method="L-BFGS-B")
        self.temperature_ = float(np.exp(res.x[0]))

        if self.is_binary:
            y = labels.astype(int)
            self.models_ = [None if np.unique(y).size < 2 else LogisticRegression(C=1.0, max_iter=200).fit(self._feat(probs), y)]
        else:
            self.models_ = []
            for c in range(self.n_classes_):
                y = (labels == c).astype(int)
                self.models_.append(None if np.unique(y).size < 2 else LogisticRegression(C=1.0, max_iter=200).fit(self._feat(probs[:, c]), y))

        t, b = self._temp_predict(probs, self.temperature_), self._beta_predict(probs)
        conf = np.maximum(probs, 1 - probs) if self.is_binary else np.max(probs, axis=1)

        def mix_loss(ab):
            w = special.expit(ab[0] * (conf - 0.5) + ab[1])
            if self.is_binary:
                q = np.clip((1 - w) * t + w * b, 1e-12, 1 - 1e-12)
                return -(labels * np.log(q) + (1 - labels) * np.log(1 - q)).mean()
            q = (1 - w[:, None]) * t + w[:, None] * b
            q = np.clip(q, 1e-12, 1.0)
            q /= q.sum(axis=1, keepdims=True)
            return -np.log(q[np.arange(len(labels)), labels.astype(int)]).mean()

        self.mix_ = optimize.minimize(mix_loss, x0=[4.0, 0.0], method="L-BFGS-B").x
        return self

    def predict_proba(self, probs):
        t, b = self._temp_predict(probs, self.temperature_), self._beta_predict(probs)
        conf = np.maximum(probs, 1 - probs) if self.is_binary else np.max(probs, axis=1)
        w = special.expit(self.mix_[0] * (conf - 0.5) + self.mix_[1])
        if self.is_binary:
            return np.clip((1 - w) * t + w * b, 0, 1)
        q = (1 - w[:, None]) * t + w[:, None] * b
        q = np.clip(q, 1e-12, 1.0)
        return q / q.sum(axis=1, keepdims=True)

class CalibrationMethod(BaseEstimator):
    """Confidence-Adaptive Ensemble Calibration.

    Combines a low-variance temperature calibrator with a higher-flexibility
    beta-style calibrator, then learns a confidence-dependent gate between them.
    A BIC-style structural-risk criterion finally selects among identity,
    temperature, beta, or adaptive mixture to avoid harming already calibrated
    models on small calibration sets.
    """

    def __init__(self):
        self.is_binary = None
        self.n_classes_ = None
        self.temperature_ = 1.0
        self.mix_ = np.zeros(2)
        self.models_ = None
        self.mode_ = "id"

    def _feat(self, p):
        p = np.clip(p, 1e-6, 1 - 1e-6)
        return np.column_stack([np.log(p), np.log(1 - p)])

    def _raw_predict(self, probs):
        if probs.ndim == 1:
            return np.clip(probs, 1e-12, 1 - 1e-12)
        q = np.clip(probs, 1e-12, 1.0)
        return q / q.sum(axis=1, keepdims=True)

    def _temp_predict(self, probs, T):
        eps = 1e-12
        if probs.ndim == 1:
            p = np.clip(probs, eps, 1 - eps)
            return special.expit((np.log(p) - np.log(1 - p)) / T)
        z = np.log(np.clip(probs, eps, 1.0)) / T
        z -= z.max(axis=1, keepdims=True)
        z = np.exp(z)
        return z / z.sum(axis=1, keepdims=True)

    def _beta_predict(self, probs):
        if self.is_binary:
            if self.models_[0] is None:
                return self._raw_predict(probs)
            return self.models_[0].predict_proba(self._feat(probs))[:, 1]
        out = np.zeros_like(probs, dtype=float)
        for c, model in enumerate(self.models_):
            out[:, c] = probs[:, c] if model is None else model.predict_proba(self._feat(probs[:, c]))[:, 1]
        out = np.clip(out, 1e-12, 1.0)
        return out / out.sum(axis=1, keepdims=True)

    def _mix_predict(self, probs, t, b):
        conf = np.maximum(probs, 1 - probs) if self.is_binary else np.max(probs, axis=1)
        w = special.expit(self.mix_[0] * (conf - 0.5) + self.mix_[1])
        if self.is_binary:
            return np.clip((1 - w) * t + w * b, 1e-12, 1 - 1e-12)
        q = (1 - w[:, None]) * t + w[:, None] * b
        q = np.clip(q, 1e-12, 1.0)
        return q / q.sum(axis=1, keepdims=True)

    def fit(self, probs, labels):
        self.is_binary = probs.ndim == 1
        self.n_classes_ = 2 if self.is_binary else probs.shape[1]
        raw = self._raw_predict(probs)

        def nll_of(q):
            q = np.column_stack([1 - q, q]) if q.ndim == 1 else q
            q = np.clip(q, 1e-12, 1 - 1e-12)
            return -np.log(q[np.arange(len(labels)), labels.astype(int)]).mean()

        res = optimize.minimize(lambda x: nll_of(self._temp_predict(probs, float(np.exp(x[0])))), x0=[0.0], bounds=[(-3, 3)], method="L-BFGS-B")
        self.temperature_ = float(np.exp(res.x[0]))

        if self.is_binary:
            y = labels.astype(int)
            self.models_ = [None if np.unique(y).size < 2 else LogisticRegression(C=0.7, max_iter=200).fit(self._feat(probs), y)]
        else:
            self.models_ = []
            for c in range(self.n_classes_):
                y = (labels == c).astype(int)
                self.models_.append(None if np.unique(y).size < 2 else LogisticRegression(C=0.7, max_iter=200).fit(self._feat(probs[:, c]), y))

        t, b = self._temp_predict(probs, self.temperature_), self._beta_predict(probs)
        self.mix_ = optimize.minimize(lambda ab: nll_of(self._mix_predict(probs, t, b) if (self.mix_.fill(0) or True) else None), x0=[0.0, 0.0], method="L-BFGS-B").x
        self.mix_ = optimize.minimize(lambda ab: nll_of((setattr(self, 'mix_', ab) or self._mix_predict(probs, t, b))), x0=self.mix_, method="L-BFGS-B").x

        df_b = 3 if self.is_binary else 3 * self.n_classes_
        bic = lambda q, df: nll_of(q) + 0.5 * df * np.log(max(len(labels), 2)) / len(labels)
        scores = {
            "id": bic(raw, 0),
            "temp": bic(t, 1),
            "beta": bic(b, df_b),
            "mix": bic(self._mix_predict(probs, t, b), df_b + 3),
        }
        self.mode_ = min(scores, key=scores.get)
        return self

    def predict_proba(self, probs):
        raw = self._raw_predict(probs)
        if self.mode_ == "id":
            return raw
        t = self._temp_predict(probs, self.temperature_)
        if self.mode_ == "temp":
            return t
        b = self._beta_predict(probs)
        if self.mode_ == "beta":
            return b
        return self._mix_predict(probs, t, b)

